"206 :   @Override
207 :   public boolean isSubtype(JSType that) {
208 :     if (JSType.isSubtypeHelper(this, that)) {
209 :       return true;
210 :     }
211 : 
212 :     // Top of the record types is the empty record, or OBJECT_TYPE.
213 :     if (registry.getNativeObjectType(
214 :             JSTypeNative.OBJECT_TYPE).isSubtype(that)) {
215 :       return true;
216 :     }
217 : 
218 :     // A type is a subtype of a record type if it itself is a record
219 :     // type and it has at least the same members as the parent record type
220 :     // with the same types.
221 :     if (!that.isRecordType()) {
222 :       return false;
223 :     }
224 : 
225 :     return RecordType.isSubtype(this, that.toMaybeRecordType());
226 :   }"

"423 :   @Override
424 :   public boolean shouldTraverse(
425 :       NodeTraversal t, Node n, Node parent) {
426 :     checkNoTypeCheckSection(n, true);
427 :     switch (n.getType()) {
428 :       case Token.FUNCTION:
429 :         // normal type checking
430 :         final Scope outerScope = t.getScope();
431 :         final String functionPrivateName = n.getFirstChild().getString();
432 :         if (functionPrivateName != null && functionPrivateName.length() > 0 &&
433 :             outerScope.isDeclared(functionPrivateName, false) &&
434 :             // Ideally, we would want to check whether the type in the scope
435 :             // differs from the type being defined, but then the extern
436 :             // redeclarations of built-in types generates spurious warnings.
437 :             !(outerScope.getVar(
438 :                 functionPrivateName).getType() instanceof FunctionType)) {
439 :           report(t, n, FUNCTION_MASKS_VARIABLE, functionPrivateName);
440 :         }
441 : 
442 :         // TODO(user): Only traverse the function's body. The function's
443 :         // name and arguments are traversed by the scope creator, and ideally
444 :         // should not be traversed by the type checker.
445 :         break;
446 :     }
447 :     return true;
448 :   }"

"460 :   @Override
461 :   public void visit(NodeTraversal t, Node n, Node parent) {
462 :     JSType childType;
463 :     JSType leftType, rightType;
464 :     Node left, right;
465 :     // To be explicitly set to false if the node is not typeable.
466 :     boolean typeable = true;
467 : 
468 :     switch (n.getType()) {
469 :       case Token.NAME:
470 :         typeable = visitName(t, n, parent);
471 :         break;
472 : 
473 :       case Token.PARAM_LIST:
474 :         // If this is under a FUNCTION node, it is a parameter list and can be
475 :         // ignored here.
476 :         if (!parent.isFunction()) {
477 :           ensureTyped(t, n, getJSType(n.getFirstChild()));
478 :         } else {
479 :           typeable = false;
480 :         }
481 :         break;
482 : 
483 :       case Token.COMMA:
484 :         ensureTyped(t, n, getJSType(n.getLastChild()));
485 :         break;
486 : 
487 :       case Token.TRUE:
488 :       case Token.FALSE:
489 :         ensureTyped(t, n, BOOLEAN_TYPE);
490 :         break;
491 : 
492 :       case Token.THIS:
493 :         ensureTyped(t, n, t.getScope().getTypeOfThis());
494 :         break;
495 : 
496 :       case Token.NULL:
497 :         ensureTyped(t, n, NULL_TYPE);
498 :         break;
499 : 
500 :       case Token.NUMBER:
501 :         ensureTyped(t, n, NUMBER_TYPE);
502 :         break;
503 : 
504 :       case Token.STRING:
505 :         // Object literal keys are handled with OBJECTLIT
506 :         if (!NodeUtil.isObjectLitKey(n, n.getParent())) {
507 :           ensureTyped(t, n, STRING_TYPE);
508 :         } else {
509 :           // Object literal keys are not typeable
510 :           typeable = false;
511 :         }
512 :         break;
513 : 
514 :       case Token.GETTER_DEF:
515 :       case Token.SETTER_DEF:
516 :         // Object literal keys are handled with OBJECTLIT
517 :         break;
518 : 
519 :       case Token.ARRAYLIT:
520 :         ensureTyped(t, n, ARRAY_TYPE);
521 :         break;
522 : 
523 :       case Token.REGEXP:
524 :         ensureTyped(t, n, REGEXP_TYPE);
525 :         break;
526 : 
527 :       case Token.GETPROP:
528 :         visitGetProp(t, n, parent);
529 :         typeable = !(parent.isAssign() &&
530 :                      parent.getFirstChild() == n);
531 :         break;
532 : 
533 :       case Token.GETELEM:
534 :         visitGetElem(t, n);
535 :         // The type of GETELEM is always unknown, so no point counting that.
536 :         // If that unknown leaks elsewhere (say by an assignment to another
537 :         // variable), then it will be counted.
538 :         typeable = false;
539 :         break;
540 : 
541 :       case Token.VAR:
542 :         visitVar(t, n);
543 :         typeable = false;
544 :         break;
545 : 
546 :       case Token.NEW:
547 :         visitNew(t, n);
548 :         typeable = true;
549 :         break;
550 : 
551 :       case Token.CALL:
552 :         visitCall(t, n);
553 :         typeable = !parent.isExprResult();
554 :         break;
555 : 
556 :       case Token.RETURN:
557 :         visitReturn(t, n);
558 :         typeable = false;
559 :         break;
560 : 
561 :       case Token.DEC:
562 :       case Token.INC:
563 :         left = n.getFirstChild();
564 :         validator.expectNumber(
565 :             t, left, getJSType(left), "increment/decrement");
566 :         ensureTyped(t, n, NUMBER_TYPE);
567 :         break;
568 : 
569 :       case Token.NOT:
570 :         ensureTyped(t, n, BOOLEAN_TYPE);
571 :         break;
572 : 
573 :       case Token.VOID:
574 :         ensureTyped(t, n, VOID_TYPE);
575 :         break;
576 : 
577 :       case Token.TYPEOF:
578 :         ensureTyped(t, n, STRING_TYPE);
579 :         break;
580 : 
581 :       case Token.BITNOT:
582 :         childType = getJSType(n.getFirstChild());
583 :         if (!childType.matchesInt32Context()) {
584 :           report(t, n, BIT_OPERATION, NodeUtil.opToStr(n.getType()),
585 :               childType.toString());
586 :         }
587 :         ensureTyped(t, n, NUMBER_TYPE);
588 :         break;
589 : 
590 :       case Token.POS:
591 :       case Token.NEG:
592 :         left = n.getFirstChild();
593 :         validator.expectNumber(t, left, getJSType(left), "sign operator");
594 :         ensureTyped(t, n, NUMBER_TYPE);
595 :         break;
596 : 
597 :       case Token.EQ:
598 :       case Token.NE: {
599 :         leftType = getJSType(n.getFirstChild());
600 :         rightType = getJSType(n.getLastChild());
601 : 
602 :         JSType leftTypeRestricted = leftType.restrictByNotNullOrUndefined();
603 :         JSType rightTypeRestricted = rightType.restrictByNotNullOrUndefined();
604 :         TernaryValue result =
605 :             leftTypeRestricted.testForEquality(rightTypeRestricted);
606 :         if (result != TernaryValue.UNKNOWN) {
607 :           if (n.isNE()) {
608 :             result = result.not();
609 :           }
610 :           report(t, n, DETERMINISTIC_TEST, leftType.toString(),
611 :               rightType.toString(), result.toString());
612 :         }
613 :         ensureTyped(t, n, BOOLEAN_TYPE);
614 :         break;
615 :       }
616 : 
617 :       case Token.SHEQ:
618 :       case Token.SHNE: {
619 :         leftType = getJSType(n.getFirstChild());
620 :         rightType = getJSType(n.getLastChild());
621 : 
622 :         JSType leftTypeRestricted = leftType.restrictByNotNullOrUndefined();
623 :         JSType rightTypeRestricted = rightType.restrictByNotNullOrUndefined();
624 :         if (!leftTypeRestricted.canTestForShallowEqualityWith(
625 :                 rightTypeRestricted)) {
626 :           report(t, n, DETERMINISTIC_TEST_NO_RESULT, leftType.toString(),
627 :               rightType.toString());
628 :         }
629 :         ensureTyped(t, n, BOOLEAN_TYPE);
630 :         break;
631 :       }
632 : 
633 :       case Token.LT:
634 :       case Token.LE:
635 :       case Token.GT:
636 :       case Token.GE:
637 :         leftType = getJSType(n.getFirstChild());
638 :         rightType = getJSType(n.getLastChild());
639 :         if (rightType.isNumber()) {
640 :           validator.expectNumber(
641 :               t, n, leftType, "left side of numeric comparison");
642 :         } else if (leftType.isNumber()) {
643 :           validator.expectNumber(
644 :               t, n, rightType, "right side of numeric comparison");
645 :         } else if (leftType.matchesNumberContext() &&
646 :                    rightType.matchesNumberContext()) {
647 :           // OK.
648 :         } else {
649 :           // Whether the comparison is numeric will be determined at runtime
650 :           // each time the expression is evaluated. Regardless, both operands
651 :           // should match a string context.
652 :           String message = "left side of comparison";
653 :           validator.expectString(t, n, leftType, message);
654 :           validator.expectNotNullOrUndefined(
655 :               t, n, leftType, message, getNativeType(STRING_TYPE));
656 :           message = "right side of comparison";
657 :           validator.expectString(t, n, rightType, message);
658 :           validator.expectNotNullOrUndefined(
659 :               t, n, rightType, message, getNativeType(STRING_TYPE));
660 :         }
661 :         ensureTyped(t, n, BOOLEAN_TYPE);
662 :         break;
663 : 
664 :       case Token.IN:
665 :         left = n.getFirstChild();
666 :         right = n.getLastChild();
667 :         leftType = getJSType(left);
668 :         rightType = getJSType(right);
669 :         validator.expectObject(t, n, rightType, "'in' requires an object");
670 :         validator.expectString(t, left, leftType, "left side of 'in'");
671 :         ensureTyped(t, n, BOOLEAN_TYPE);
672 :         break;
673 : 
674 :       case Token.INSTANCEOF:
675 :         left = n.getFirstChild();
676 :         right = n.getLastChild();
677 :         leftType = getJSType(left);
678 :         rightType = getJSType(right).restrictByNotNullOrUndefined();
679 : 
680 :         validator.expectAnyObject(
681 :             t, left, leftType, "deterministic instanceof yields false");
682 :         validator.expectActualObject(
683 :             t, right, rightType, "instanceof requires an object");
684 :         ensureTyped(t, n, BOOLEAN_TYPE);
685 :         break;
686 : 
687 :       case Token.ASSIGN:
688 :         visitAssign(t, n);
689 :         typeable = false;
690 :         break;
691 : 
692 :       case Token.ASSIGN_LSH:
693 :       case Token.ASSIGN_RSH:
694 :       case Token.ASSIGN_URSH:
695 :       case Token.ASSIGN_DIV:
696 :       case Token.ASSIGN_MOD:
697 :       case Token.ASSIGN_BITOR:
698 :       case Token.ASSIGN_BITXOR:
699 :       case Token.ASSIGN_BITAND:
700 :       case Token.ASSIGN_SUB:
701 :       case Token.ASSIGN_ADD:
702 :       case Token.ASSIGN_MUL:
703 :       case Token.LSH:
704 :       case Token.RSH:
705 :       case Token.URSH:
706 :       case Token.DIV:
707 :       case Token.MOD:
708 :       case Token.BITOR:
709 :       case Token.BITXOR:
710 :       case Token.BITAND:
711 :       case Token.SUB:
712 :       case Token.ADD:
713 :       case Token.MUL:
714 :         visitBinaryOperator(n.getType(), t, n);
715 :         break;
716 : 
717 :       case Token.DELPROP:
718 :         ensureTyped(t, n, BOOLEAN_TYPE);
719 :         break;
720 : 
721 :       case Token.CASE:
722 :         JSType switchType = getJSType(parent.getFirstChild());
723 :         JSType caseType = getJSType(n.getFirstChild());
724 :         validator.expectSwitchMatchesCase(t, n, switchType, caseType);
725 :         typeable = false;
726 :         break;
727 : 
728 :       case Token.WITH: {
729 :         Node child = n.getFirstChild();
730 :         childType = getJSType(child);
731 :         validator.expectObject(
732 :             t, child, childType, "with requires an object");
733 :         typeable = false;
734 :         break;
735 :       }
736 : 
737 :       case Token.FUNCTION:
738 :         visitFunction(t, n);
739 :         break;
740 : 
741 :       // These nodes have no interesting type behavior.
742 :       case Token.LABEL:
743 :       case Token.LABEL_NAME:
744 :       case Token.SWITCH:
745 :       case Token.BREAK:
746 :       case Token.CATCH:
747 :       case Token.TRY:
748 :       case Token.SCRIPT:
749 :       case Token.EXPR_RESULT:
750 :       case Token.BLOCK:
751 :       case Token.EMPTY:
752 :       case Token.DEFAULT_CASE:
753 :       case Token.CONTINUE:
754 :       case Token.DEBUGGER:
755 :       case Token.THROW:
756 :         typeable = false;
757 :         break;
758 : 
759 :       // These nodes require data flow analysis.
760 :       case Token.DO:
761 :       case Token.FOR:
762 :       case Token.IF:
763 :       case Token.WHILE:
764 :         typeable = false;
765 :         break;
766 : 
767 :       // These nodes are typed during the type inference.
768 :       case Token.AND:
769 :       case Token.HOOK:
770 :       case Token.OBJECTLIT:
771 :       case Token.OR:
772 :         if (n.getJSType() != null) { // If we didn't run type inference.
773 :           ensureTyped(t, n);
774 :         } else {
775 :           // If this is an enum, then give that type to the objectlit as well.
776 :           if ((n.isObjectLit())
777 :               && (parent.getJSType() instanceof EnumType)) {
778 :             ensureTyped(t, n, parent.getJSType());
779 :           } else {
780 :             ensureTyped(t, n);
781 :           }
782 :         }
783 :         if (n.isObjectLit()) {
784 :           for (Node key : n.children()) {
785 :             visitObjLitKey(t, key, n);
786 :           }
787 :         }
788 :         break;
789 : 
790 :       default:
791 :         report(t, n, UNEXPECTED_TOKEN, Token.name(n.getType()));
792 :         ensureTyped(t, n);
793 :         break;
794 :     }
795 : 
796 :     // Don't count externs since the user's code may not even use that part.
797 :     typeable = typeable && !inExterns;
798 : 
799 :     if (typeable) {
800 :       doPercentTypedAccounting(t, n);
801 :     }
802 : 
803 :     checkNoTypeCheckSection(n, false);
804 :   }"

"1489 :   private void visitFunction(NodeTraversal t, Node n) {
1490 :     FunctionType functionType = JSType.toMaybeFunctionType(n.getJSType());
1491 :     String functionPrivateName = n.getFirstChild().getString();
1492 :     if (functionType.isConstructor()) {
1493 :       FunctionType baseConstructor = functionType.getSuperClassConstructor();
1494 :       if (baseConstructor != null &&
1495 :           baseConstructor != getNativeType(OBJECT_FUNCTION_TYPE) &&
1496 :           (baseConstructor.isInterface() && functionType.isConstructor())) {
1497 :         compiler.report(
1498 :             t.makeError(n, CONFLICTING_EXTENDED_TYPE, functionPrivateName));
1499 :       } else {
1500 :         // All interfaces are properly implemented by a class
1501 :         for (JSType baseInterface : functionType.getImplementedInterfaces()) {
1502 :           boolean badImplementedType = false;
1503 :           ObjectType baseInterfaceObj = ObjectType.cast(baseInterface);
1504 :           if (baseInterfaceObj != null) {
1505 :             FunctionType interfaceConstructor =
1506 :               baseInterfaceObj.getConstructor();
1507 :             if (interfaceConstructor != null &&
1508 :                 !interfaceConstructor.isInterface()) {
1509 :               badImplementedType = true;
1510 :             }
1511 :           } else {
1512 :             badImplementedType = true;
1513 :           }
1514 :           if (badImplementedType) {
1515 :             report(t, n, BAD_IMPLEMENTED_TYPE, functionPrivateName);
1516 :           }
1517 :         }
1518 :         // check properties
1519 :         validator.expectAllInterfaceProperties(t, n, functionType);
1520 :       }
1521 :     } else if (functionType.isInterface()) {
1522 :       // Interface must extend only interfaces
1523 :       for (ObjectType extInterface : functionType.getExtendedInterfaces()) {
1524 :         if (extInterface.getConstructor() != null
1525 :             && !extInterface.getConstructor().isInterface()) {
1526 :           compiler.report(
1527 :               t.makeError(n, CONFLICTING_EXTENDED_TYPE, functionPrivateName));
1528 :         }
1529 :       }
1530 :       // Interface cannot implement any interfaces
1531 :       if (functionType.hasImplementedInterfaces()) {
1532 :         compiler.report(t.makeError(n,
1533 :             CONFLICTING_IMPLEMENTED_TYPE, functionPrivateName));
1534 :       }
1535 :       // Check whether the extended interfaces have any conflicts
1536 :       if (functionType.getExtendedInterfacesCount() > 1) {
1537 :         // Only check when extending more than one interfaces
1538 :         HashMap<String, ObjectType> properties
1539 :             = new HashMap<String, ObjectType>();
1540 :         HashMap<String, ObjectType> currentProperties
1541 :             = new HashMap<String, ObjectType>();
1542 :         for (ObjectType interfaceType : functionType.getExtendedInterfaces()) {
1543 :           currentProperties.clear();
1544 :           checkInterfaceConflictProperties(t, n, functionPrivateName,
1545 :               properties, currentProperties, interfaceType);
1546 :           properties.putAll(currentProperties);
1547 :         }
1548 :       }
1549 :     }
1550 :   }"

"780 :   private FlowScope traverseCall(Node n, FlowScope scope) {
781 :     scope = traverseChildren(n, scope);
782 : 
783 :     Node left = n.getFirstChild();
784 :     JSType functionType = getJSType(left).restrictByNotNullOrUndefined();
785 :     if (functionType != null) {
786 :       if (functionType.isFunctionType()) {
787 :         FunctionType fnType = functionType.toMaybeFunctionType();
788 :         n.setJSType(fnType.getReturnType());
789 :         backwardsInferenceFromCallSite(n, fnType);
790 :       } else if (functionType.equals(getNativeType(CHECKED_UNKNOWN_TYPE))) {
791 :         n.setJSType(getNativeType(CHECKED_UNKNOWN_TYPE));
792 :       }
793 :     }
794 : 
795 :     scope = tightenTypesAfterAssertions(scope, n);
796 :     return scope;
797 :   }"

"2072 :   static JSType getObjectLitKeyTypeFromValueType(Node key, JSType valueType) {
2073 :     if (valueType != null) {
2074 :       switch (key.getType()) {
2075 :         case Token.GETTER_DEF:
2076 :           // GET must always return a function type.
2077 :           if (valueType.isFunctionType()) {
2078 :             FunctionType fntype = valueType.toMaybeFunctionType();
2079 :             valueType = fntype.getReturnType();
2080 :           } else {
2081 :             return null;
2082 :           }
2083 :           break;
2084 :         case Token.SETTER_DEF:
2085 :           if (valueType.isFunctionType()) {
