351 :       case Token.LT:
352 :       case Token.LE:
353 :       case Token.GT:
354 :       case Token.GE:
355 :       case Token.NOT:
356 :       case Token.EQ:
357 :       case Token.NE:
358 :       case Token.SHEQ:
359 :       case Token.SHNE:
